using System;
using System.Linq;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Core
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Immutable.
    /// Corners are stored in order around the panel; edge i runs from corner i to corner i+1.
    /// </summary>
    public sealed class Panel
    {
        private readonly Point3d[] _corners;

        public Panel(Point3d[] corners, int index)
        {
            if (corners == null) throw new ArgumentNullException(nameof(corners));
            if (corners.Length != 4) throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            _corners = (Point3d[])corners.Clone();
            Index = index;

            EdgeLengths = new double[4];
            for (int i = 0; i < 4; i++)
                EdgeLengths[i] = _corners[i].DistanceTo(_corners[(i + 1) % 4]);

            Diagonals = new[]
            {
                _corners[0].DistanceTo(_corners[2]),
                _corners[1].DistanceTo(_corners[3]),
            };

            // Area of the two triangles either side of the 0-2 diagonal (exact for planar panels).
            Area = 0.5 * Vector3d.CrossProduct(_corners[1] - _corners[0], _corners[2] - _corners[0]).Length
                 + 0.5 * Vector3d.CrossProduct(_corners[2] - _corners[0], _corners[3] - _corners[0]).Length;

            Center = new Point3d(
                _corners.Average(p => p.X),
                _corners.Average(p => p.Y),
                _corners.Average(p => p.Z));

            var plane = new Plane(_corners[0], _corners[1], _corners[2]);
            Deviation = plane.IsValid ? Math.Abs(plane.DistanceTo(_corners[3])) : 0.0;
        }

        /// <summary>Position of the panel in the grid it was cut from.</summary>
        public int Index { get; }

        /// <summary>Copy of the four corners, in order around the panel.</summary>
        public Point3d[] Corners => (Point3d[])_corners.Clone();

        public Point3d Corner(int i) => _corners[i];

        public double Area { get; }

        public Point3d Center { get; }

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation { get; }

        /// <summary>Lengths of edges 0-1, 1-2, 2-3, 3-0.</summary>
        public double[] EdgeLengths { get; }

        /// <summary>Lengths of diagonals 0-2 and 1-3.</summary>
        public double[] Diagonals { get; }

        /// <summary>Width of the panel's fabrication rectangle: mean of first and third edge.</summary>
        public double RectWidth => 0.5 * (EdgeLengths[0] + EdgeLengths[2]);

        /// <summary>Height of the panel's fabrication rectangle: mean of second and fourth edge.</summary>
        public double RectHeight => 0.5 * (EdgeLengths[1] + EdgeLengths[3]);

        public Polyline OutlinePolyline()
        {
            return new Polyline(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });
        }

        public Curve Outline() => new PolylineCurve(OutlinePolyline());

        public BoundingBox BoundingBox => new BoundingBox(_corners);

        public Panel Transformed(Transform xform)
        {
            var pts = Corners;
            for (int i = 0; i < 4; i++) pts[i].Transform(xform);
            return new Panel(pts, Index);
        }

        public override string ToString() => $"Panel {Index} (area {Area:0.###}, dev {Deviation:0.###})";
    }
}

