using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Core
{
    /// <summary>Cuts a surface into a grid of panels.</summary>
    public static class Panelizer
    {
        /// <summary>
        /// Divides the surface domain evenly into uCount x vCount cells. Index runs along U first,
        /// then V: index = j * uCount + i.
        /// </summary>
        public static List<Panel> Panelize(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentNullException(nameof(surface));
            if (uCount < 1 || vCount < 1) throw new ArgumentOutOfRangeException(nameof(uCount), "Counts must be at least 1.");

            Interval du = surface.Domain(0);
            Interval dv = surface.Domain(1);

            // Sample the grid of corner points once; neighbouring panels share them.
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
            {
                double u = du.ParameterAt((double)i / uCount);
                for (int j = 0; j <= vCount; j++)
                    grid[i, j] = surface.PointAt(u, dv.ParameterAt((double)j / vCount));
            }

            var panels = new List<Panel>(uCount * vCount);
            for (int j = 0; j < vCount; j++)
            {
                for (int i = 0; i < uCount; i++)
                {
                    var corners = new[] { grid[i, j], grid[i + 1, j], grid[i + 1, j + 1], grid[i, j + 1] };
                    panels.Add(new Panel(corners, j * uCount + i));
                }
            }
            return panels;
        }
    }

    public enum PanelType
    {
        Flat,
        ColdBent,
        Custom,
    }

    public static class PanelClassifier
    {
        public const double ColdBentFactor = 10.0;

        public static bool IsFlat(Panel panel, double tolerance) => panel.Deviation <= tolerance;

        public static PanelType Classify(Panel panel, double tolerance)
        {
            if (panel.Deviation <= tolerance) return PanelType.Flat;
            if (panel.Deviation <= ColdBentFactor * tolerance) return PanelType.ColdBent;
            return PanelType.Custom;
        }

        public static string Label(PanelType type)
        {
            switch (type)
            {
                case PanelType.Flat: return "flat";
                case PanelType.ColdBent: return "cold-bent";
                default: return "custom";
            }
        }
    }

    public static class PanelGrouper
    {
        /// <summary>
        /// Groups panels whose sorted edge lengths and sorted diagonals each differ by at most tolerance.
        /// Groups are numbered from 0 in order of first appearance; each group is compared against
        /// its representative (first member).
        /// </summary>
        public static int[] Group(IReadOnlyList<Panel> panels, double tolerance, out List<int> representativeIndices)
        {
            var groups = new int[panels.Count];
            var repSignatures = new List<double[]>();
            representativeIndices = new List<int>();

            for (int p = 0; p < panels.Count; p++)
            {
                double[] sig = Signature(panels[p]);
                int found = -1;
                for (int g = 0; g < repSignatures.Count; g++)
                {
                    if (Matches(sig, repSignatures[g], tolerance)) { found = g; break; }
                }
                if (found < 0)
                {
                    found = repSignatures.Count;
                    repSignatures.Add(sig);
                    representativeIndices.Add(p);
                }
                groups[p] = found;
            }
            return groups;
        }

        private static double[] Signature(Panel panel)
        {
            var edges = panel.EdgeLengths.OrderBy(x => x);
            var diags = panel.Diagonals.OrderBy(x => x);
            return edges.Concat(diags).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }
    }

    public static class CutList
    {
        public const string Header = "index,width,height,area,deviation";

        public static string ToCsv(IEnumerable<Panel> panels)
        {
            var ci = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.Append(Header).Append('\n');
            foreach (var p in panels)
            {
                sb.Append(p.Index.ToString(ci)).Append(',')
                  .Append(p.RectWidth.ToString("R", ci)).Append(',')
                  .Append(p.RectHeight.ToString("R", ci)).Append(',')
                  .Append(p.Area.ToString("R", ci)).Append(',')
                  .Append(p.Deviation.ToString("R", ci)).Append('\n');
            }
            return sb.ToString();
        }
    }
}

