            }
        }
    }

    public static class PanelGrouper
    {
        /// <summary>
        /// Groups panels whose sorted edge lengths and sorted diagonals each differ by at most tolerance.
        /// Groups are numbered from 0 in order of first appearance; each group is compared against
        /// its representative (first member).
        /// </summary>
        public static int[] Group(IReadOnlyList<Panel> panels, double tolerance, out List<int> representativeIndices)
        {
            var groups = new int[panels.Count];
            var repSignatures = new List<double[]>();
            representativeIndices = new List<int>();

            for (int p = 0; p < panels.Count; p++)
            {
                double[] sig = Signature(panels[p]);
                int found = -1;
                for (int g = 0; g < repSignatures.Count; g++)
                {
                    if (Matches(sig, repSignatures[g], tolerance)) { found = g; break; }
                }
                if (found < 0)
                {
                    found = repSignatures.Count;
                    repSignatures.Add(sig);
                    representativeIndices.Add(p);
                }
                groups[p] = found;
            }
            return groups;
        }

        private static double[] Signature(Panel panel)
        {
            var edges = panel.EdgeLengths.OrderBy(x => x);
            var diags = panel.Diagonals.OrderBy(x => x);
            return edges.Concat(diags).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }
    }

    public static class CutList
    {
        public const string Header = "index,width,height,area,deviation";

        public static string ToCsv(IEnumerable<Panel> panels)
        {
            var ci = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.Append(Header).Append('\n');
            foreach (var p in panels)
            {
                sb.Append(p.Index.ToString(ci)).Append(',')
                  .Append(p.RectWidth.ToString("R", ci)).Append(',')
                  .Append(p.RectHeight.ToString("R", ci)).Append(',')
                  .Append(p.Area.ToString("R", ci)).Append(',')
                  .Append(p.Deviation.ToString("R", ci)).Append('\n');
            }
            return sb.ToString();
        }
    }
}

