        public double Width { get; }
        public double Height { get; }
    }

    public readonly struct Placement
    {
        public Placement(int id, int sheet, double x, double y, double width, double height, bool turned)
        {
            Id = id; Sheet = sheet; X = x; Y = y; Width = width; Height = height; Turned = turned;
        }

        public int Id { get; }
        public int Sheet { get; }
        /// <summary>Lower-left corner in sheet-local coordinates.</summary>
        public double X { get; }
        public double Y { get; }
        /// <summary>Placed size (already swapped when turned).</summary>
        public double Width { get; }
        public double Height { get; }
        public bool Turned { get; }
    }

    public sealed class NestResult
    {
        public List<Placement> Placements { get; } = new List<Placement>();
        public List<int> Unplaced { get; } = new List<int>();
        public int SheetCount { get; set; }
        public double SheetWidth { get; set; }
        public double SheetHeight { get; set; }

        public double PlacedArea => Placements.Sum(p => p.Width * p.Height);

        public double Utilization =>
            SheetCount == 0 ? 0.0 : PlacedArea / (SheetCount * SheetWidth * SheetHeight);
    }

    /// <summary>
    /// Shelf nesting: parts sorted tallest first, filled left to right on shelves; a new shelf starts
    /// above the current one when a part does not fit, a new sheet when the shelf does not fit.
    /// A part is turned 90 degrees only when it fits turned but not as is.
    /// Spacing is kept between parts, between shelves and from the sheet edges.
    /// </summary>
    public static class ShelfNester
    {
        public static NestResult Nest(
            IReadOnlyList<NestPart> parts,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<double> progress = null,
            CancellationToken cancel = default)
        {
            var result = new NestResult { SheetWidth = sheetWidth, SheetHeight = sheetHeight };

            double maxX = sheetWidth - spacing;
            double maxY = sheetHeight - spacing;

            // Stable sort, tallest first.
            var order = parts.Select((p, i) => (part: p, i))
                             .OrderByDescending(t => t.part.Height)
                             .ThenBy(t => t.i)
                             .Select(t => t.part)
                             .ToList();

            int sheet = -1;          // no sheet opened yet
            double shelfY = spacing; // bottom of current shelf
            double shelfH = 0;       // height of current shelf
            double x = spacing;      // next free x on current shelf
            bool shelfEmpty = true;

            int reportEvery = Math.Max(1, order.Count / 200);

            for (int n = 0; n < order.Count; n++)
            {
                cancel.ThrowIfCancellationRequested();
                if (progress != null && n % reportEvery == 0) progress.Report((double)n / order.Count);

                NestPart part = order[n];
                double w = part.Width, h = part.Height;

                bool fitsSheet = (spacing + w <= maxX && spacing + h <= maxY)
                              || (spacing + h <= maxX && spacing + w <= maxY);
                if (!fitsSheet || w <= 0 || h <= 0 || double.IsNaN(w) || double.IsNaN(h))
                {
                    result.Unplaced.Add(part.Id);
                    continue;
                }

                if (sheet < 0) { sheet = 0; }

                // 1. current shelf
                if (TryShelf(w, h, x, shelfY, maxX, maxY, out double pw, out double ph, out bool turned))
                {
                    Place();
                    continue;
                }

                // 2. new shelf above (pointless if the current shelf is empty)
                if (!shelfEmpty)
                {
                    double newY = shelfY + shelfH + spacing;
                    if (TryShelf(w, h, spacing, newY, maxX, maxY, out pw, out ph, out turned))
                    {
                        shelfY = newY; shelfH = 0; x = spacing; shelfEmpty = true;
                        Place();
                        continue;
                    }
                }

                // 3. new sheet (always fits, checked above)
                sheet++;
                shelfY = spacing; shelfH = 0; x = spacing; shelfEmpty = true;
                TryShelf(w, h, x, shelfY, maxX, maxY, out pw, out ph, out turned);
                Place();

                void Place()
                {
                    result.Placements.Add(new Placement(part.Id, sheet, x, shelfY, pw, ph, turned));
                    x += pw + spacing;
                    shelfH = Math.Max(shelfH, ph);
                    shelfEmpty = false;
                }
            }

            result.SheetCount = sheet + 1;
            progress?.Report(1.0);
            return result;
        }

        private static bool TryShelf(double w, double h, double x, double y, double maxX, double maxY,
                                     out double pw, out double ph, out bool turned)
        {
            if (x + w <= maxX && y + h <= maxY) { pw = w; ph = h; turned = false; return true; }
            if (x + h <= maxX && y + w <= maxY) { pw = h; ph = w; turned = true; return true; }
            pw = ph = 0; turned = false;
            return false;
        }
    }
}

