using System;
using BenchPlugin.Facade.Core;
using GH_IO.Serialization;
using GH_IO.Types;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Params
{
    /// <summary>Grasshopper wrapper for a <see cref="Panel"/>: one value per panel on a wire.</summary>
    public class GH_Panel : GH_Goo<Panel>, IGH_PreviewData
    {
        public GH_Panel() { }
        public GH_Panel(Panel panel) : base(panel) { }
        public GH_Panel(GH_Panel other) : base(other?.Value) { }

        public override bool IsValid => Value != null;
        public override string IsValidWhyNot => Value == null ? "No panel" : string.Empty;
        public override string TypeName => "Panel";
        public override string TypeDescription => "A four-sided facade panel";

        // Panel is immutable, so sharing the instance is safe.
        public override IGH_Goo Duplicate() => new GH_Panel(Value);

        public override string ToString() => Value == null ? "Null panel" : Value.ToString();

        public override bool CastFrom(object source)
        {
            switch (source)
            {
                case Panel p: Value = p; return true;
                case GH_Panel g: Value = g.Value; return true;
                default: return false;
            }
        }

        public override bool CastTo<Q>(ref Q target)
        {
            if (Value == null) return false;

            if (typeof(Q).IsAssignableFrom(typeof(Panel)))
            {
                target = (Q)(object)Value;
                return true;
            }
            if (typeof(Q).IsAssignableFrom(typeof(GH_Curve)))
            {
                target = (Q)(object)new GH_Curve(Value.Outline());
                return true;
            }
            if (typeof(Q).IsAssignableFrom(typeof(Curve)))
            {
                target = (Q)(object)Value.Outline();
                return true;
            }
            if (typeof(Q).IsAssignableFrom(typeof(GH_Integer)))
            {
                target = (Q)(object)new GH_Integer(Value.Index);
                return true;
            }
            return false;
        }

        // ---- preview -------------------------------------------------------

        public BoundingBox ClippingBox => Value?.BoundingBox ?? BoundingBox.Empty;

        public void DrawViewportWires(GH_PreviewWireArgs args)
        {
            if (Value == null) return;
            args.Pipeline.DrawPolyline(Value.OutlinePolyline(), args.Color, args.Thickness);
        }

        public void DrawViewportMeshes(GH_PreviewMeshArgs args) { }

        // ---- serialization (for internalised data) -------------------------

        public override bool Write(GH_IWriter writer)
        {
            if (Value != null)
            {
                writer.SetInt32("Index", Value.Index);
                for (int i = 0; i < 4; i++)
                {
                    var c = Value.Corner(i);
                    writer.SetPoint3D("Corner", i, new GH_Point3D(c.X, c.Y, c.Z));
                }
            }
            return true;
        }

        public override bool Read(GH_IReader reader)
        {
            Value = null;
            if (!reader.ItemExists("Index")) return true;
            var corners = new Point3d[4];
            for (int i = 0; i < 4; i++)
            {
                var p = reader.GetPoint3D("Corner", i);
                corners[i] = new Point3d(p.x, p.y, p.z);
            }
            Value = new Panel(corners, reader.GetInt32("Index"));
            return true;
        }
    }
}

