namespace BenchPlugin.Facade.Components
{
    public class PanelizeSurfaceComponent : GH_Component
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize",
                   "Cut a surface into a grid of four-sided panels by dividing its domain evenly",
                   FacadeInfo.Category, FacadeInfo.SubPanels)
        {
        }

        public override Guid ComponentGuid => new Guid("1f4b8c2e-93d7-4a61-b0e5-7c2a9d3f6e18");
        public override GH_Exposure Exposure => GH_Exposure.primary;

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddSurfaceParameter("Surface", "S", "Surface to panelize", GH_ParamAccess.item);
            pManager.AddIntegerParameter("U Count", "U", "Number of panels in the U direction", GH_ParamAccess.item, 10);
            pManager.AddIntegerParameter("V Count", "V", "Number of panels in the V direction", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels, indexed along U first, then V", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outlines", "O", "Closed panel outlines", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface surface = null;
            int uCount = 10, vCount = 6;
            if (!DA.GetData(0, ref surface) || surface == null) return;
            if (!DA.GetData(1, ref uCount)) return;
            if (!DA.GetData(2, ref vCount)) return;

            if (uCount < 1 || vCount < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error,
                    $"U Count and V Count must be at least 1 (got U={uCount}, V={vCount}).");
                return;
            }

            var panels = Panelizer.Panelize(surface, uCount, vCount);
            DA.SetDataList(0, PanelData.Wrap(panels));
            DA.SetDataList(1, panels.Select(p => p.Outline()));
        }
    }

    public class PanelInfoComponent : GH_Component
    {
        public PanelInfoComponent()
            : base("Panel Info", "PInfo", "Take a panel apart into its properties",
                   FacadeInfo.Category, FacadeInfo.SubPanels)
        {
        }

        public override Guid ComponentGuid => new Guid("8a3d5e71-2b6c-4f90-a1d8-5e7b0c9f2a34");
        public override GH_Exposure Exposure => GH_Exposure.primary;

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panel", "P", "Panel to inspect", GH_ParamAccess.item);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddPointParameter("Corners", "C", "The four corners, in order around the panel", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outline", "O", "Closed panel outline", GH_ParamAccess.item);
            pManager.AddNumberParameter("Area", "A", "Panel area", GH_ParamAccess.item);
            pManager.AddPointParameter("Center", "Ce", "Average of the four corners", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Index", "I", "Index of the panel in its grid", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            GH_Panel goo = null;
            if (!DA.GetData(0, ref goo) || goo?.Value == null) return;
            Panel panel = goo.Value;

            DA.SetDataList(0, panel.Corners);
            DA.SetData(1, panel.Outline());
            DA.SetData(2, panel.Area);
            DA.SetData(3, panel.Center);
            DA.SetData(4, panel.Index);
        }
    }
}

