using System;
using System.Collections.Generic;
using System.Linq;
using BenchPlugin.Facade.Core;
using BenchPlugin.Facade.Params;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class PlanarityComponent : GH_Component
    {
        public PlanarityComponent()
            : base("Planarity", "Planar",
                   "Measure how far each panel is from flat (distance from the fourth corner to the plane of the other three)",
                   FacadeInfo.Category, FacadeInfo.SubAnalysis)
        {
        }

        public override Guid ComponentGuid => new Guid("c5e1a7f3-6d2b-48a9-9f04-3b8e2d7c1a56");
        public override GH_Exposure Exposure => GH_Exposure.primary;

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels to analyse", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum deviation for a panel to count as flat", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Planarity deviation per panel", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "True per panel when Deviation is at most Tolerance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double tol = 0.5;
            if (!PanelData.GetPanels(DA, 0, out List<Panel> panels)) return;
            if (!DA.GetData(1, ref tol)) return;

            var deviation = panels.Select(p => p.Deviation).ToList();
            var flat = panels.Select(p => PanelClassifier.IsFlat(p, tol)).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;

            if (notFlat > panels.Count / 2.0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{notFlat} of {panels.Count} panels are not flat (deviation above {tol}).");
            }

            DA.SetDataList(0, deviation);
            DA.SetDataList(1, flat);
            DA.SetData(2, flatCount);
        }
    }

    public class ClassifyPanelsComponent : GH_Component
    {
        public ClassifyPanelsComponent()
            : base("Classify Panels", "Classify",
                   "Classify panels as flat, cold-bent (deviation up to 10x tolerance) or custom",
                   FacadeInfo.Category, FacadeInfo.SubAnalysis)
        {
        }

        public override Guid ComponentGuid => new Guid("4b7f2c9e-1a85-4d36-8e0b-6f3c5a9d2e71");
        public override GH_Exposure Exposure => GH_Exposure.primary;

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels to classify", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Flatness tolerance", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("Type", "T", "\"flat\", \"cold-bent\" or \"custom\" per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "F", "Number of flat panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Cold Bent Count", "B", "Number of cold-bent panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Custom Count", "C", "Number of custom panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double tol = 0.5;
            if (!PanelData.GetPanels(DA, 0, out List<Panel> panels)) return;
            if (!DA.GetData(1, ref tol)) return;

            var types = panels.Select(p => PanelClassifier.Classify(p, tol)).ToList();

            DA.SetDataList(0, types.Select(PanelClassifier.Label));
            DA.SetData(1, types.Count(t => t == PanelType.Flat));
            DA.SetData(2, types.Count(t => t == PanelType.ColdBent));
            DA.SetData(3, types.Count(t => t == PanelType.Custom));
        }
    }

    public class PanelStatsComponent : GH_Component
    {
        public PanelStatsComponent()
            : base("Panel Stats", "Stats", "Area statistics for a set of panels",
                   FacadeInfo.Category, FacadeInfo.SubAnalysis)
        {
        }

        public override Guid ComponentGuid => new Guid("e9d3b6a2-7f14-4c58-b2a7-0d5e8f1c3b94");
        public override GH_Exposure Exposure => GH_Exposure.secondary;

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels to measure", GH_ParamAccess.list);
            // Optional so an empty input reaches SolveInstance and gets a proper error.
            pManager[0].Optional = true;
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "T", "Sum of panel areas", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Mean", "Mean panel area", GH_ParamAccess.item);
        }

