    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group",
                   "Group panels whose sorted edge lengths and sorted diagonals each match within tolerance",
                   FacadeInfo.Category, FacadeInfo.SubFabrication)
        {
        }

        public override Guid ComponentGuid => new Guid("2d8e4f1b-5a93-4c07-a6e2-9b1f7c3d5e80");
        public override GH_Exposure Exposure => GH_Exposure.primary;

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels to group", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum length difference for panels to count as identical", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel, from 0 in order of first appearance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParameter(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double tol = 1.0;
            if (!PanelData.GetPanels(DA, 0, out List<Panel> panels)) return;
            if (!DA.GetData(1, ref tol)) return;
            if (tol < 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Tolerance must not be negative.");
                return;
            }

            int[] groups = PanelGrouper.Group(panels, tol, out List<int> reps);

            DA.SetDataList(0, groups);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, PanelData.Wrap(reps.Select(i => panels[i])));
        }
    }

    public class CutListComponent : GH_Component
    {
        public CutListComponent()
            : base("Cut List", "CutList",
                   "CSV cut list (index, width, height, area, deviation), optionally written to a file",
                   FacadeInfo.Category, FacadeInfo.SubFabrication)
        {
        }

