        {
            pManager.AddParameter(new PanelParameter(), "Panels", "P", "Panels to list", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "F", "File to write the CSV to", GH_ParamAccess.item, string.Empty);
            pManager.AddBooleanParameter("Write", "W", "Write the CSV to Path", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list as CSV text", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "OK", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            string path = string.Empty;
            bool write = false;
            if (!PanelData.GetPanels(DA, 0, out List<Panel> panels)) return;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            string csv = CutList.ToCsv(panels);
            DA.SetData(0, csv);

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                }
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, $"Could not write '{path}': {ex.Message}");
                    }
                }
            }
            DA.SetData(1, written);
        }
    }
}

