using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using BenchPlugin.Facade.Core;
using BenchPlugin.Facade.Params;
using Grasshopper;
using Grasshopper.Kernel;
using Rhino;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Components
{
    /// <summary>
    /// Nests panel rectangles on sheets with a shelf algorithm.
    ///
    /// The nesting runs on a background task so Grasshopper stays responsive:
    ///  1. A normal solution collects one job per iteration and starts the task (outputs stay empty,
    ///     the component message shows progress).
    ///  2. Any new solution (inputs changed) cancels the running task and starts a new one.
    ///  3. When the task finishes it hops back to the UI thread and expires the component; that
    ///     "delivery" solution only copies the finished results to the outputs.
    /// </summary>
    public class NestOnSheetsComponent : GH_Component
    {
